    ("基準期間", "きじゅんきかん", "kỳ tính thuế căn cứ (niên độ 2 năm trước)", "Kỳ kế toán 2 năm trước dùng để xác định xem doanh nghiệp năm nay có thuộc diện phải nộp thuế tiêu dùng hay không.", "Base period", "PRO-A2", 94, "nta_code_index:6501", [], ["特定期間"], ["免税事業者", "課税事業者"]),
    ("特定期間", "とくていきかん", "kỳ tính thuế bổ sung (6 tháng đầu năm trước)", "Khoảng thời gian 6 tháng đầu của năm trước dùng để xét nhanh nghĩa vụ nộp thuế tiêu dùng nếu doanh số vượt 1,000 vạn yên.", "Specified period", "PRO-A2", 92, "nta_code_index:6501", [], ["基準期間"], ["課税事業者"]),
    ("免税事業者", "めんぜいじぎょうしゃ", "doanh nghiệp được miễn nghĩa vụ nộp thuế tiêu dùng", "Hộ kinh doanh hoặc công ty có doanh số bán hàng trong kỳ căn cứ dưới 1,000 vạn yên không phải nộp thuế tiêu dùng.", "Tax-exempt business operator", "PRO-A1", 98, "nta_code_index:6501", [], ["課税事業者"], ["インボイス制度", "益税"]),
    ("課税事業者", "かぜいじぎょうしゃ", "doanh nghiệp thuộc diện phải nộp thuế tiêu dùng", "Pháp nhân hoặc cá nhân có doanh số vượt 1,000 vạn yên hoặc đã tự nguyện đăng ký nộp thuế tiêu dùng.", "Taxable business operator", "PRO-A1", 99, "nta_code_index:6121", [], ["免税事業者"], ["適格請求書発行事業者", "仕入税額控除"]),
    ("総額表示", "そうがくひょうじ", "quy định niêm yết giá đã bao gồm thuế", "Quy định bắt buộc người bán phải ghi rõ tổng số tiền đã bao gồm thuế tiêu dùng trên bảng giá hàng hóa phục vụ người mua.", "Total price display obligation", "PRO-A1", 96, "nta_code_index:6902", [], [], ["税込価格", "値札"]),
    ("税抜経理方式", "ぜいぬきけいりほうしき", "phương pháp hạch toán kế toán tách riêng thuế", "Phương pháp ghi chép doanh thu và chi phí theo giá chưa thuế, thuế tiêu dùng được theo dõi riêng vào tài khoản tạm thu/tạm trả.", "Tax-exclusive accounting method", "PRO-A2", 94, "nta_code_index:6375", [], ["税込経理方式"], ["仮払消費税", "仮受消費税"]),
    ("税込経理方式", "ぜいこみけいりほうしき", "phương pháp hạch toán kế toán gộp chung thuế", "Phương pháp ghi nhận doanh thu và chi phí gộp luôn tiền thuế tiêu dùng vào giá trị hàng hóa.", "Tax-inclusive accounting method", "PRO-A2", 93, "nta_code_index:6375", [], ["税抜経理方式"], ["租税公課"]),
    ("控除対象外消費税額等", "こうじょたいしょうがいしょうひぜいがくとう", "khoản thuế tiêu dùng đầu vào không được khấu trừ", "Số thuế tiêu dùng đã trả khi mua tài sản nhưng không đủ điều kiện khấu trừ hết, phải chuyển vào chi phí hoặc vốn hóa vào tài sản.", "Non-deductible consumption tax", "PRO-A3", 90, "nta_code_index:6921", [], [], ["課税売上割合", "資産計上"]),
    ("輸出免税", "ゆしゅつめんぜい", "miễn thuế tiêu dùng cho hàng hóa xuất khẩu", "Chế độ áp thuế suất 0% đối với hàng hóa xuất khẩu ra nước ngoài và được hoàn lại toàn bộ số thuế tiêu dùng đã nộp ở khâu mua trong nước.", "Export tax exemption", "PRO-A2", 95, "nta_code_index:6551", [], [], ["輸出取引", "消費税還付"]),
    ("輸入消費税", "ゆにゅうしょうひぜい", "thuế tiêu dùng đánh trên hàng nhập khẩu", "Thuế tiêu dùng do hải quan thu đối với hàng hóa nhập khẩu từ nước ngoài vào lãnh thổ Nhật Bản trước khi thông quan.", "Import consumption tax", "PRO-A2", 94, "nta_code_index:6563", [], [], ["関税", "通関"]),
    ("2割特例", "にわりとくれい", "chính sách ưu đãi thuế tiêu dùng nộp 20% (cho người mới lên nộp thuế)", "Chính sách hỗ trợ quá độ cho phép các hộ kinh doanh cá thể mới chuyển sang nộp thuế tiêu dùng chỉ phải nộp 20% số thuế thu được.", "Special 20% tax rule", "PRO-A1", 97, "nta_code_index:invoice", [], [], ["インボイス特例", "免税事業者"]),
    ("少額特例", "しょうがくとくれい", "quy định miễn hóa đơn đối với giao dịch nhỏ dưới 1 vạn yên", "Chế độ cho phép doanh nghiệp vừa và nhỏ được khấu trừ thuế đầu vào chỉ cần sổ sách đối với các khoản chi tiêu dưới 10,000 yên.", "Special small-amount exception", "PRO-A2", 94, "nta_code_index:invoice", [], [], ["帳簿保存", "インボイス"]),
    ("適格簡易請求書", "てきかくかんいせいきゅうしょ", "hóa đơn giản đơn đạt chuẩn (biên lai siêu thị, taxi)", "Biên lai rút gọn được cấp cho ngành bán lẻ, taxi, nhà hàng không cần ghi tên khách hàng mà vẫn đủ điều kiện khấu trừ thuế.", "Simplified qualified invoice", "PRO-A1", 95, "nta_code_index:6498", ["簡易インボイス"], [], ["レシート", "小売業"]),
    ("電子インボイス", "でんしいんぼいす", "hóa đơn điện tử đạt chuẩn (Peppol)", "Hóa đơn đạt chuẩn được phát hành và lưu trữ dưới dạng dữ liệu số hóa theo định dạng chuẩn quốc tế Peppol.", "Electronic invoice (e-Invoice)", "PRO-A2", 95, "nta_code_index:invoice", ["Peppol"], [], ["電子帳簿保存法", "デジタルインボイス"]),
    ("リバースチャージ方式", "りばーすちゃーじほうしき", "cơ chế tự nộp thuế thay cho nhà cung cấp nước ngoài", "Cơ chế người mua dịch vụ kỹ thuật số từ các công ty nước ngoài (như Google, Meta) phải tự kê khai và nộp thuế tiêu dùng thay.", "Reverse charge mechanism", "PRO-A3", 89, "nta_code_index:6118", [], [], ["国境越え役務提供", "クロスボーダー取引"]),
    ("電気通信利用役務の提供", "でんきつうしんりようえきむのていきょう", "dịch vụ kỹ thuật số xuyên biên giới", "Các dịch vụ cung cấp qua internet như dịch vụ lưu trữ đám mây, phần mềm SaaS, tải nhạc từ nước ngoài vào Nhật.", "Provision of telecommunications services", "PRO-A3", 89, "nta_code_index:6118", [], [], ["リバースチャージ方式", "プラットフォーム課税"]),

    # --- 7. Withholding Tax & Year-End Adjustments (146-175) ---
    ("源泉徴収", "げんせんちょうしゅう", "khấu trừ thuế tại nguồn", "Cơ chế cơ quan chi trả tiền (như công ty) khấu trừ một khoản thuế thu nhập trước khi chuyển tiền trả cho người lao động hoặc đối tác.", "Withholding tax", "PRO-A1", 100, "nta_code_index:2110", [], [], ["源泉徴収票", "年末調整"]),
    ("源泉徴収義務者", "げんせんちょうしゅうぎむしゃ", "người có nghĩa vụ khấu trừ thuế tại nguồn", "Pháp nhân hoặc cá nhân sử dụng lao động có trách nhiệm pháp lý phải trừ thuế và nộp tiền vào ngân sách nhà nước.", "Withholding agent", "PRO-A2", 95, "nta_code_index:2110", [], [], ["給与支払者", "法定調書"]),
    ("源泉所得税", "げんせんしょとくぜい", "tiền thuế thu nhập cá nhân bị khấu trừ tại nguồn", "Số tiền thuế TNCN đã bị đơn vị chi trả khấu trừ và nộp thay cho người có thu nhập vào ngày 10 hàng tháng.", "Withheld income tax", "PRO-A1", 98, "nta_code_index:2110", [], [], ["納期の特例", "源泉徴収簿"]),
    ("年末調整", "ねんまつちょうせい", "quyết toán thuế cuối năm tại nơi làm việc", "Thủ tục kế toán của công ty vào tháng 12 hàng năm để cân đối lại số thuế thu nhập đã tạm trừ cả năm với số thuế thực tế phải nộp của nhân viên.", "Year-end tax adjustment", "PRO-A1", 100, "nta_code_index:nemmatsuchosei", [], [], ["源泉徴収票", "扶養控除等申告書", "確定申告"]),
    ("源泉徴収票", "げんせんちょうしゅうひょう", "phiếu xác nhận thu nhập và số thuế đã khấu trừ trong năm", "Giấy chứng nhận thu nhập và số thuế do công ty cấp cho nhân viên vào cuối năm, là chứng từ bắt buộc khi vay mua nhà hoặc làm visa.", "Withholding tax slip", "PRO-A1", 100, "nta_code_index:7411", [], [], ["支払金額", "源泉徴収税額", "給与所得"]),
    ("支払調書", "しはらいちょうしょ", "bản kê khai thanh toán thù lao cho đối tác bên ngoài", "Chứng từ do công ty gửi cho cơ quan thuế và người nhận thù lao (luật sư, chuyên gia, biên phiên dịch, người làm tự do).", "Payment record / Payment statement", "PRO-A1", 96, "nta_code_index:7431", [], [], ["源泉徴収", "法定調書"]),
    ("法定調書", "ほうていちょうしょ", "các báo cáo thuế bắt buộc nộp hàng năm theo luật", "Tập hợp các tài liệu như phiếu thu nhập, bảng kê thù lao mà doanh nghiệp phải nộp cho cơ quan thuế trước ngày 31 tháng 1.", "Statutory reports", "PRO-A2", 93, "nta_code_index:7451", [], [], ["法定調書合計表", "支払調書"]),
    ("法定調書合計表", "ほうていちょうしょごうけいひょう", "bảng tổng hợp các chứng từ khấu trừ thuế bắt buộc", "Tờ khai tổng hợp toàn bộ số tiền lương, tiền thù lao và số thuế đã khấu trừ trong suốt 1 năm nộp cho cơ quan thuế.", "Summary table of statutory reports", "PRO-A2", 93, "nta_code_index:7451", [], [], ["法定調書", "給与支払報告書"]),
    ("納期の特例", "のうきのとくれい", "chế độ đặc cách nộp thuế khấu trừ 6 tháng một lần", "Ưu đãi cho doanh nghiệp có dưới 10 nhân viên được gom tiền thuế TNCN đã trừ nộp 2 lần/năm (tháng 7 và tháng 1) thay vì nộp hàng tháng.", "Special exception for due date of tax withholding", "PRO-A2", 94, "nta_code_index:2505", [], [], ["源泉所得税", "中小企業特例"]),
    ("扶養控除等申告書", "ふようこうじょとうしんこくしょ", "tờ khai người phụ thuộc giảm trừ gia cảnh (Mẫu cơ bản)", "Tờ khai nhân viên bắt buộc phải nộp cho công ty vào đầu mỗi năm để được áp dụng biểu thuế khấu trừ theo hàng chính thức (Kou-ran).", "Declaration of exemption for dependents", "PRO-A1", 99, "nta_code_index:nemmatsuchosei", ["マル扶"], [], ["年末調整", "給与所得者の扶養控除"]),
    ("基礎控除申告書", "きそこうじょしんこくしょ", "tờ khai giảm trừ bản thân và vợ chồng cuối năm", "Mẫu đơn nộp trong đợt quyết toán thuế cuối năm để xác định mức giảm trừ bản thân và giảm trừ vợ/chồng.", "Declaration of basic exemption", "PRO-A1", 97, "nta_code_index:nemmatsuchosei", ["マル基"], [], ["年末調整", "配偶者控除"]),
    ("保険料控除申告書", "ほけんりょうこうじょしんこくしょ", "tờ khai giảm trừ các khoản bảo hiểm nhân thọ, động đất", "Tờ khai kèm chứng từ nộp cho công ty vào tháng 11 để được trừ tiền bảo hiểm nhân thọ và hưu trí vào thu nhập.", "Declaration of insurance deduction", "PRO-A1", 97, "nta_code_index:nemmatsuchosei", ["マル保"], [], ["年末調整", "控除証明書"]),
    ("給与支払報告書", "きゅうよしはらいほうこくしょ", "báo cáo tổng tiền lương nộp cho chính quyền địa phương", "Tài liệu công ty gửi cho UBND quận/huyện nơi nhân viên cư trú để chính quyền tính số thuế cư trú cho năm sau.", "Report on payment of salaries", "PRO-A2", 94, "nta_code_index:nemmatsuchosei", [], [], ["住民税", "特別徴収"]),
    ("特別徴収", "とくべつちょうしゅう", "thuế cư trú trừ trực tiếp vào lương hàng tháng", "Phương thức công ty trừ tiền thuế cư trú trực tiếp từ lương của nhân viên từ tháng 6 đến tháng 5 năm sau để nộp thay cho địa phương.", "Special collection of residence tax", "PRO-A1", 98, "nta_code_index:nemmatsuchosei", [], ["普通徴収"], ["住民税", "特別徴収税額通知書"]),
    ("普通徴収", "ふつうちょうしゅう", "tự cầm giấy báo nộp thuế cư trú tại ngân hàng/cửa hàng tiện lợi", "Hình thức người nộp thuế tự cầm phiếu thông báo do địa phương gửi về để đi nộp thuế thành 4 đợt trong năm.", "Ordinary collection of residence tax", "PRO-A1", 96, "nta_code_index:nemmatsuchosei", [], ["特別徴収"], ["住民税納付書", "コンビニ納付"]),
    ("甲欄", "こうらん", "cột A trên bảng thuế khấu trừ (áp dụng cho công việc chính)", "Mức thuế khấu trừ ưu đãi thấp áp dụng cho nhân viên đã nộp tờ khai người phụ thuộc cho công ty nơi làm việc chính.", "Column A of tax withholding table", "PRO-A2", 93, "nta_code_index:2511", [], ["乙欄", "丙欄"], ["扶養控除等申告書"]),
    ("乙欄", "おつらん", "cột B trên bảng thuế khấu trừ (áp dụng cho công việc làm thêm/phụ)", "Mức thuế khấu trừ cao áp dụng cho người làm thêm, làm việc bán thời gian tại nơi thứ hai mà chưa nộp tờ khai giảm trừ.", "Column B of tax withholding table", "PRO-A2", 93, "nta_code_index:2511", [], ["甲欄"], ["副業", "2か所以上から給与"]),
    ("丙欄", "へいらん", "cột C trên bảng thuế khấu trừ (lao động thời vụ ngắn hạn)", "Mức thuế khấu trừ áp dụng cho lao động thuê theo ngày hoặc thời vụ ngắn hạn dưới 2 tháng.", "Column C of tax withholding table", "PRO-A3", 88, "nta_code_index:2511", [], ["甲欄", "乙欄"], ["日雇い労働者"]),
    ("報酬・料金等の源泉徴収", "ほうしゅうりょうきんとうのげんせんちょうしゅう", "khấu trừ thuế thu nhập đối với tiền thù lao chuyên gia (10.21%)", "Nghĩa vụ trừ 10.21% thuế thu nhập khi trả tiền thù lao viết bài, dịch thuật, thiết kế hoặc tư vấn chuyên môn.", "Withholding tax on remuneration and fees", "PRO-A1", 97, "nta_code_index:2792", [], [], ["支払調書", "外注費"]),
    ("非居住者の源泉徴収", "ひきょじゅうしゃのげんせんちょうしゅう", "khấu trừ thuế tại nguồn đối với người không cư trú (20.42%)", "Quy định khấu trừ 20.42% thuế khi chuyển tiền thù lao, tiền bản quyền hoặc lương cho cá nhân sống ngoài nước Nhật.", "Withholding tax for non-residents", "PRO-A2", 92, "nta_code_index:2875", [], [], ["租税条約", "非居住者"]),

