    ("税務調査", "ぜいむちょうさ", "thanh tra thuế / kiểm tra thuế", "Việc cơ quan thuế đến trực tiếp trụ sở doanh nghiệp để kiểm tra sổ sách, tài khoản ngân hàng và hóa đơn chứng từ.", "Tax audit / Tax inspection", "PRO-A1", 99, "nta_code_index:tax_audit", [], [], ["実地調査", "税理士", "修正申告"]),
    ("実地調査", "じっちちょうさ", "thanh tra thực tế tại hiện trường", "Đoàn thanh tra thuế trực tiếp có mặt tại văn phòng, cửa hàng hoặc nhà máy của doanh nghiệp để rà soát thực tế.", "Field audit / On-site tax audit", "PRO-A2", 94, "nta_code_index:tax_audit", [], [], ["税務調査", "臨場調査"]),
