# Write out tax.py
with open(OUT_FILE, "w", encoding="utf-8") as f:
    f.write('"""\nscripts/pilot_builder/tax.py\nAuthoritative 200 canonical tax learning entries.\n"""\n\n')
    f.write('TAX_ITEMS = [\n')
    for item in TAX_DEFINITIONS:
        surface, reading, vi_short, vi_exp, en_pref, tier, priority, src_ref, syns, ants, rels = item
        entry_dict = {
            "surface": surface,
            "reading": reading,
            "vi_short": vi_short,
            "vi_explanation": vi_exp,
            "en_preferred": en_pref,
            "tier": tier,
            "priority": priority,
            "source_reference": src_ref,
            "synonyms": syns,
            "antonyms": ants,
            "related_terms": rels
        }
        f.write("    " + json.dumps(entry_dict, ensure_ascii=False) + ",\n")
    f.write(']\n')

print(f"[+] Wrote {len(TAX_DEFINITIONS)} entries to {OUT_FILE.relative_to(BASE_DIR)}")
